import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { emitTokensContractCss, flattenTokens, type StyleDescriptor } from "@/features/designs/lib/styleContract";

// #2567: `tokens-contract.css` is GENERATED from `style-descriptor.json` (the design-system SoT).
// This is the generator + the drift guard: `UPDATE_KITS=1 npx vitest run styleContract.gen`
// (re)writes the CSS from the descriptor; CI asserts it stays in sync, so the contract can't silently
// drift from the descriptor (and thus from what `bsc ui tokens` will report). Read via fs (not a JSON
// import) so the test doesn't depend on resolveJsonModule; normalise CRLF → LF for cross-platform.
const DESCRIPTOR_FILE = join(process.cwd(), "src-tauri/data/ui/style-descriptor.json");
const CSS_FILE = join(process.cwd(), "src-tauri/data/ui/tokens-contract.css");
const descriptor = JSON.parse(readFileSync(DESCRIPTOR_FILE, "utf8")) as StyleDescriptor;
const css = emitTokensContractCss(descriptor);

describe("tokens-contract.css ↔ style-descriptor.json (#2567)", () => {
  it("is generated verbatim from the style descriptor (UPDATE_KITS=1 to regenerate)", () => {
    if (process.env.UPDATE_KITS) writeFileSync(CSS_FILE, css);
    expect(existsSync(CSS_FILE), "tokens-contract.css missing — run `UPDATE_KITS=1 npx vitest run styleContract.gen`").toBe(true);
    expect(readFileSync(CSS_FILE, "utf8").replace(/\r\n/g, "\n")).toBe(css);
  });

  it("declares EVERY descriptor token as a `--name:` line (the Rust contract parser's precondition)", () => {
    // crates/bsc-ui lib.rs:207 parses trimmed lines starting with `--` up to `:` — every token the
    // descriptor defines (and every theme override references) must appear as such a declaration.
    const declared = new Set(
      css.split("\n").map((l) => l.trim()).filter((l) => l.startsWith("--")).map((l) => l.split(":")[0].trim()),
    );
    for (const t of flattenTokens(descriptor)) {
      expect(declared.has(t.name), `${t.name} must be declared in the emitted contract`).toBe(true);
    }
    // spot-check the semantic set the Rust test asserts by name
    expect(declared.has("--card-bg") && declared.has("--chip-border")).toBe(true);
  });

  it("defines the motion tokens (#2866) — durations + easings in the base palette", () => {
    const flat = flattenTokens(descriptor);
    // Durations + easings live in `base` (app primitives, like the radii) so themes can re-time them
    // and components/animations reference them by name.
    expect(flat.find((t) => t.name === "--dur-base")).toMatchObject({ family: "base", type: "duration", default: "220ms" });
    expect(flat.find((t) => t.name === "--dur-fast")?.type).toBe("duration");
    expect(flat.find((t) => t.name === "--dur-slow")?.type).toBe("duration");
    expect(flat.find((t) => t.name === "--ease-standard")).toMatchObject({ family: "base", type: "easing" });
    expect(flat.find((t) => t.name === "--ease-emphasized")?.type).toBe("easing");
    // and they emit into the contract CSS as var-referenceable declarations.
    expect(css).toContain("--dur-base: 220ms;");
    expect(css).toContain("--ease-standard: cubic-bezier(0.4, 0, 0.2, 1);");
  });

  it("flattens base + component + per-variant tokens in order, with rung-2 addressing intact", () => {
    const flat = flattenTokens(descriptor);
    expect(flat.filter((t) => t.family === "base")).toHaveLength(descriptor.base.length);
    // btn's `primary` variant tokens carry component + variant + key so `component btn set-token bg
    // --variant primary` resolves to `--btn-primary-bg`.
    const p = flat.find((t) => t.name === "--btn-primary-bg")!;
    expect(p).toMatchObject({ component: "btn", variant: "primary", key: "bg" });
    // base tokens carry no component/variant/key.
    const accent = flat.find((t) => t.name === "--accent")!;
    expect(accent.family).toBe("base");
    expect(accent.component).toBeUndefined();
    // domain / categorical tokens (#2607) flatten with family = the group, a key, and NO component —
    // they're contract vocabulary a kit consumes, not a component surface.
    const err = flat.find((t) => t.name === "--graph-health-error");
    expect(err).toMatchObject({ family: "graph-health", key: "error" });
    expect(err?.component).toBeUndefined();
  });
});

import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import type { StyleDescriptor } from "@/features/designs/lib/styleContract";

// #2567 follow-up: the style descriptor (src-tauri/data/ui/style-descriptor.json) is the SoT that
// generates `tokens-contract.css` (the emit contract for a GENERATED app) AND backs `bsc ui tokens`.
// But base-studio-code's OWN live stylesheet is `src/styles/tokens.css` — a SEPARATE file that
// hand-defines the same semantic tokens. If the two drift, `bsc ui tokens` would describe values the
// running app doesn't actually use (an LLM tunes a token that no longer means what the tool says).
// This guard asserts the descriptor's tokens ARE the app's live BASE values, so the discovery surface
// stays truthful. (A later slice may generate the tokens.css token block from the descriptor outright;
// for now the guard is the reconciliation — the descriptor is authoritative, this catches divergence.)
const TOKENS_CSS = join(process.cwd(), "src/styles/tokens.css");
const DESCRIPTOR = join(process.cwd(), "src-tauri/data/ui/style-descriptor.json");

/** The FIRST `--token: value;` for each token — the base `:root` value the descriptor represents. A
 *  later surface/theme block re-declaring a token (e.g. the light surface) is a scoped override, not
 *  the base, so the first occurrence wins. Scans the whole file (declarations can share a line, e.g.
 *  `--r-sm: 4px; --r-md: 6px; --r-lg: 10px;`). */
function firstTokenValues(css: string): Map<string, string> {
  const m = new Map<string, string>();
  const re = /(--[a-z0-9-]+)\s*:\s*([^;]+);/g;
  for (let match = re.exec(css); match; match = re.exec(css)) {
    if (!m.has(match[1])) m.set(match[1], match[2].trim());
  }
  return m;
}

describe("style descriptor ↔ the app's live tokens.css (#2567)", () => {
  it("every descriptor token is defined in src/styles/tokens.css with the SAME base value", () => {
    const live = firstTokenValues(readFileSync(TOKENS_CSS, "utf8"));
    const d = JSON.parse(readFileSync(DESCRIPTOR, "utf8")) as StyleDescriptor;
    const expected: { name: string; value: string }[] = [
      ...d.base.map((b) => ({ name: b.name, value: b.value })),
      ...d.components.flatMap((c) => [
        ...c.tokens.map((t) => ({ name: t.name, value: t.default })),
        ...c.variants.flatMap((v) => v.tokens.map((t) => ({ name: t.name, value: t.default }))),
      ]),
      // Domain / categorical tokens (#2607) are app-live too — a kit consumes them, so they must be
      // declared in tokens.css with the descriptor's literal value or `bsc ui tokens` would lie.
      ...(d.domain ?? []).flatMap((g) => g.tokens.map((t) => ({ name: t.name, value: t.value }))),
    ];
    const missing = expected.filter((e) => !live.has(e.name)).map((e) => e.name);
    const mismatched = expected
      .filter((e) => live.has(e.name) && live.get(e.name) !== e.value)
      .map((e) => `${e.name}: descriptor='${e.value}' vs tokens.css='${live.get(e.name)}'`);
    expect(missing, `descriptor tokens absent from src/styles/tokens.css: ${missing.join(", ")}`).toEqual([]);
    expect(mismatched, `descriptor ↔ tokens.css drift:\n${mismatched.join("\n")}`).toEqual([]);
  });
});
